'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
let p = 0;

const L = Number(input[p++]);
const C = Number(input[p++]);

const rows = [];
const equations = [];
const adjacency = Array.from({ length: 26 * 26 }, () => []);

function addEquation(ids, sum) {
  const counts = new Map();
  for (const id of ids) counts.set(id, (counts.get(id) || 0) + 1);

  const terms = Array.from(counts, ([id, count]) => [id, count]);
  const index = equations.length;
  equations.push({ terms, remaining: terms.length, rhs: sum });

  for (const [id] of terms) adjacency[id].push(index);
}

function variableId(name) {
  return (name.charCodeAt(0) - 97) * 26 + name.charCodeAt(1) - 97;
}

for (let r = 0; r < L; r++) {
  const ids = [];
  for (let c = 0; c < C; c++) ids.push(variableId(input[p++]));
  rows.push(ids);
  addEquation(ids, Number(input[p++]));
}

const columnSums = [];
for (let c = 0; c < C; c++) columnSums.push(Number(input[p++]));

for (let c = 0; c < C; c++) {
  const ids = [];
  for (let r = 0; r < L; r++) ids.push(rows[r][c]);
  addEquation(ids, columnSums[c]);
}

const values = Array(26 * 26).fill(undefined);
const queue = [];

for (let i = 0; i < equations.length; i++) {
  if (equations[i].remaining === 1) queue.push(i);
}

let head = 0;
while (head < queue.length) {
  const equation = equations[queue[head++]];
  if (equation.remaining !== 1) continue;

  let unknownId = -1;
  let coefficient = 0;
  for (const [id, count] of equation.terms) {
    if (values[id] === undefined) {
      unknownId = id;
      coefficient = count;
      break;
    }
  }
  if (unknownId === -1) continue;

  const value = equation.rhs / coefficient;
  values[unknownId] = value;

  for (const equationIndex of adjacency[unknownId]) {
    const current = equations[equationIndex];
    for (const [id, count] of current.terms) {
      if (id === unknownId) {
        current.rhs -= count * value;
        current.remaining--;
        if (current.remaining === 1) queue.push(equationIndex);
        break;
      }
    }
  }
}

const output = [];
for (let id = 0; id < values.length; id++) {
  if (values[id] !== undefined) {
    const name = String.fromCharCode(97 + Math.floor(id / 26), 97 + (id % 26));
    output.push(`${name} ${values[id]}`);
  }
}

console.log(output.join('\n'));
